#!/usr/bin/env python3
"""V7.3 Daily self-healing patch component."""

def _replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label} expected one match, found {count}")
    return text.replace(old, new, 1)

def apply_daily_identify_patch(text):
    old = '''    def _vision_identify_screen(self, ref):\n        best_name = "UNKNOWN"\n        best_avg = 999.0\n        best_dists = []\n        for name, cfg in VISION_SCREEN_SIGNATURES.items():\n            dists = []\n            for roi, expected in zip(cfg.get("rois", []), cfg.get("hashes", [])):\n                got = self._daily_phash(ref, roi)\n                dists.append(self._daily_hamming(got, expected) if got is not None else 64)\n            if not dists:\n                continue\n            avg = float(sum(dists)) / len(dists)\n            if avg < best_avg:\n                best_name, best_avg, best_dists = name, avg, dists\n        cfg = VISION_SCREEN_SIGNATURES.get(best_name, {})\n        limit = float(cfg.get("max_avg", 12.0))\n        if best_avg > limit:\n            conf = max(0.0, 100.0 - best_avg * 3.0)\n            return "UNKNOWN", conf, f"nearest {best_name} d={best_avg:.1f}"\n        conf = max(0.0, min(100.0, 100.0 - (best_avg / max(1.0, limit)) * 28.0))\n        return best_name, conf, f"d={best_avg:.1f} {best_dists}"\n'''
    new = '''    def _vision_adaptive_state(self):\n        cached = getattr(self, "_vision_adaptive_cache", None)\n        if isinstance(cached, dict):\n            return cached\n        state = {"schema": 1, "screens": {}}\n        try:\n            if VISION_ADAPTIVE_FILE.exists():\n                saved = json.loads(VISION_ADAPTIVE_FILE.read_text(encoding="utf-8"))\n                if isinstance(saved, dict) and isinstance(saved.get("screens"), dict):\n                    state["screens"] = saved["screens"]\n        except Exception:\n            pass\n        self._vision_adaptive_cache = state\n        return state\n\n    def _vision_save_adaptive(self):\n        try:\n            state = self._vision_adaptive_state()\n            tmp = VISION_ADAPTIVE_FILE.with_suffix(".tmp")\n            tmp.write_text(json.dumps(state, indent=2) + "\\n", encoding="utf-8")\n            os.replace(tmp, VISION_ADAPTIVE_FILE)\n            return True\n        except Exception:\n            return False\n\n    def _vision_learn_screen(self, name, ref, evidence="OCR"):\n        """Persist a live pHash only after independent screen evidence."""\n        name = str(name or "").upper()\n        if name not in {"MAIL", "SHOP", "QUEST", "EVENT", "RECRUIT", "CHAIN"}:\n            return False\n        cfg = VISION_SCREEN_SIGNATURES.get(name) or {}\n        rois = list(cfg.get("rois") or [])\n        hashes = []\n        for roi in rois:\n            value = self._daily_phash(ref, roi)\n            if value is None:\n                return False\n            hashes.append(int(value))\n        if not hashes:\n            return False\n        state = self._vision_adaptive_state()\n        samples = state.setdefault("screens", {}).setdefault(name, [])\n        for sample in samples:\n            old_hashes = sample.get("hashes") if isinstance(sample, dict) else None\n            if not isinstance(old_hashes, list) or len(old_hashes) != len(hashes):\n                continue\n            avg = sum(self._daily_hamming(int(a), int(b)) for a, b in zip(hashes, old_hashes)) / float(len(hashes))\n            if avg <= 3.0:\n                return False\n        samples.append({\n            "hashes": hashes,\n            "evidence": str(evidence or "verified")[:40],\n            "learned_at": datetime.now().isoformat(timespec="seconds"),\n        })\n        if len(samples) > 6:\n            del samples[:-6]\n        saved = self._vision_save_adaptive()\n        if saved:\n            self.add_log(f"Daily Vision learned live {name} fingerprint ({evidence})")\n        return saved\n\n    def _vision_identify_screen(self, ref):\n        candidates = []\n        adaptive = self._vision_adaptive_state().get("screens") or {}\n        for name, cfg in VISION_SCREEN_SIGNATURES.items():\n            rois = list(cfg.get("rois") or [])\n            static_hashes = list(cfg.get("hashes") or [])\n            if rois and len(rois) == len(static_hashes):\n                candidates.append((name, rois, static_hashes, float(cfg.get("max_avg", 12.0)), "static"))\n            for idx, sample in enumerate(adaptive.get(name) or []):\n                hashes = sample.get("hashes") if isinstance(sample, dict) else None\n                if isinstance(hashes, list) and rois and len(hashes) == len(rois):\n                    # Learned samples must match more tightly than factory refs.\n                    candidates.append((name, rois, hashes, min(float(cfg.get("max_avg", 12.0)), 9.0), f"adaptive#{idx + 1}"))\n\n        best_name = "UNKNOWN"\n        best_avg = 999.0\n        best_dists = []\n        best_limit = 12.0\n        best_source = "none"\n        for name, rois, expected_hashes, limit, source in candidates:\n            dists = []\n            for roi, expected in zip(rois, expected_hashes):\n                got = self._daily_phash(ref, roi)\n                dists.append(self._daily_hamming(got, int(expected)) if got is not None else 64)\n            if not dists:\n                continue\n            avg = float(sum(dists)) / len(dists)\n            if avg < best_avg:\n                best_name, best_avg, best_dists = name, avg, dists\n                best_limit, best_source = float(limit), source\n        if best_avg > best_limit:\n            conf = max(0.0, 100.0 - best_avg * 3.0)\n            return "UNKNOWN", conf, f"nearest {best_name} d={best_avg:.1f} via {best_source}"\n        conf = max(0.0, min(100.0, 100.0 - (best_avg / max(1.0, best_limit)) * 28.0))\n        return best_name, conf, f"d={best_avg:.1f} {best_dists} via {best_source}"\n'''
    text = _replace_once(text, old, new, "Daily adaptive screen identification")
    return text
